$sPath = 'd:/Code/FHIRViewer/src/main/java/com/spiraleyes/fhirviewer/service/scripting/ScriptingSession.java'
`$content = Get-Content `$sPath -Raw -Encoding utf8
`$old = 'if (stopPending) {' + [Environment]::NewLine + '    if (stoppedRunId == 0 || stoppedRunId == myRun) {' + [Environment]::NewLine + '        // Stop arrived before a run was in flight (or this exact run): apply.' + [Environment]::NewLine + '        stopPending = false;' + [Environment]::NewLine + '        stoppedRunId = myRun;' + [Environment]::NewLine + '        stopRequested = false;' + [Environment]::NewLine + '    } else {' + [Environment]::NewLine + '        // Stop targeted an earlier run: stale, clear it.' + [Environment]::NewLine + '        stopPending = false;' + [Environment]::NewLine + '        stoppedRunId = 0;' + [Environment]::NewLine + '        stopRequested = false;' + [Environment]::NewLine + '    }' + [Environment]::NewLine + '} else {' + [Environment]::NewLine + '    stoppedRunId = 0;' + [Environment]::NewLine + '}'`n`$new = 'if (stopPending) {' + [Environment]::NewLine + '    if (stoppedRunId == 0 || stoppedRunId == myRun) {' + [Environment]::NewLine + '        // Stop arrived before a run was in flight (or this exact run): apply.' + [Environment]::NewLine + '        stopPending = false;' + [Environment]::NewLine + '        stoppedRunId = myRun;' + [Environment]::NewLine + '        // Do NOT clear stopRequested: it was set by stop() and' + [Environment]::NewLine + '        // must stay true so evaluatePart() can report STOPPED.' + [Environment]::NewLine + '    } else {' + [Environment]::NewLine + '        // Stop targeted an earlier run: stale, clear it.' + [Environment]::NewLine + '        stopPending = false;' + [Environment]::NewLine + '        stoppedRunId = 0;' + [Environment]::NewLine + '        stopRequested = false;' + [Environment]::NewLine + '    }' + [Environment]::NewLine + '} else {' + [Environment]::NewLine + '    stoppedRunId = 0;' + [Environment]::NewLine + '}'
`$content = `$content -replace [regex]::Escape(`$old), `$new
`$content | Set-Content `$sPath -Encoding utf8 -NoNewline
